package transaction

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"sort"
	"time"

	"github.com/schnurbus/go-kegelmaster/backend/internal/db"
)

var (
	// ErrNotEditable is returned when a booking generated by a game day
	// (base fee, penalty fee) is to be edited. Those are corrected on the
	// game day itself, otherwise the fee lines and the ledger diverge.
	ErrNotEditable = errors.New("only manual transactions can be edited")
	// ErrPlayerRequired is returned when a deposit or tip names no player.
	ErrPlayerRequired = errors.New("player required for deposits and tips")
)

// UpdateTransactionParams holds the new values of an edited manual booking.
// Amount is signed as stored: positive for deposit and tip, negative for
// expense.
type UpdateTransactionParams struct {
	ClubID          string
	PlayerID        *string
	TransactionType TransactionType
	Amount          int
	Description     string
	// TransactionDate keeps the stored date when zero.
	TransactionDate time.Time
}

func validateUpdateParams(params UpdateTransactionParams) error {
	if !params.TransactionType.IsManual() {
		return ErrInvalidType
	}
	if params.Amount == 0 || params.Amount > MaxAmount || params.Amount < -MaxAmount {
		return ErrInvalidAmount
	}
	if (params.TransactionType == TransactionTypeExpense) != (params.Amount < 0) {
		return ErrInvalidAmount
	}
	if params.TransactionType != TransactionTypeExpense && params.PlayerID == nil {
		return ErrPlayerRequired
	}
	return nil
}

// balanceEffects returns how a booking changes the player and the club
// balance. It mirrors the rules of createInTx and of the recalculate queries
// (player: base_fee, fee, deposit; club cash: deposit, tip, expense).
func balanceEffects(txType TransactionType, amount int) (playerDelta, clubDelta int) {
	switch txType {
	case TransactionTypeBaseFee, TransactionTypeFee:
		return amount, 0
	case TransactionTypeDeposit:
		return amount, amount
	case TransactionTypeTip, TransactionTypeExpense:
		return 0, amount
	}
	return 0, 0
}

// Update edits a manual booking (deposit, tip, expense). In one database
// transaction the old booking's effect on the player and club balances is
// reversed and the new one applied, so the stored balances keep matching
// start balance + ledger sum (what recalculate-balance computes). Bookings
// created by a game day cannot be edited (ErrNotEditable).
//
// The edited row gets fresh balance snapshots as if it were booked now;
// snapshots of other rows are historical and stay untouched, like on delete.
func (r *Repository) Update(ctx context.Context, id string, params UpdateTransactionParams) (*Transaction, error) {
	if err := validateUpdateParams(params); err != nil {
		return nil, err
	}

	tx, err := r.database.BeginTx(ctx, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to begin transaction: %w", err)
	}
	defer tx.Rollback()
	qtx := r.queries.WithTx(tx)
	now := time.Now()

	old, err := qtx.GetTransactionByIDForUpdate(ctx, id)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("failed to get transaction: %w", err)
	}
	if old.ClubID != params.ClubID {
		return nil, ErrNotFound
	}
	oldType := TransactionType(old.TransactionType)
	if !oldType.IsManual() || old.GameDayID != nil || old.GameDayFeeID != nil {
		return nil, ErrNotEditable
	}

	// Lock the old and the new player in ID order (like the game-day booking).
	var lockIDs []string
	if old.PlayerID != nil {
		lockIDs = append(lockIDs, *old.PlayerID)
	}
	if params.PlayerID != nil && (old.PlayerID == nil || *old.PlayerID != *params.PlayerID) {
		lockIDs = append(lockIDs, *params.PlayerID)
	}
	sort.Strings(lockIDs)
	original := make(map[string]int, len(lockIDs))
	balances := make(map[string]int, len(lockIDs))
	for _, pid := range lockIDs {
		p, err := lockPlayer(ctx, qtx, pid, params.ClubID)
		if err != nil {
			return nil, err
		}
		original[pid] = int(p.Balance)
		balances[pid] = int(p.Balance)
	}

	oldPlayerDelta, oldClubDelta := balanceEffects(oldType, int(old.Amount))
	newPlayerDelta, newClubDelta := balanceEffects(params.TransactionType, params.Amount)

	// Reverse the old booking, then apply the new one.
	if old.PlayerID != nil {
		balances[*old.PlayerID] -= oldPlayerDelta
	}
	var playerBalanceBefore, playerBalanceAfter *int
	if params.PlayerID != nil {
		before := balances[*params.PlayerID]
		playerBalanceBefore = &before
		balances[*params.PlayerID] += newPlayerDelta
		if params.TransactionType != TransactionTypeExpense {
			after := balances[*params.PlayerID]
			playerBalanceAfter = &after
		}
	}
	for _, pid := range lockIDs {
		if balances[pid] == original[pid] {
			continue
		}
		if err := qtx.UpdatePlayerBalance(ctx, db.UpdatePlayerBalanceParams{
			ID:        pid,
			Balance:   int32(balances[pid]),
			UpdatedAt: now,
		}); err != nil {
			return nil, fmt.Errorf("failed to update player balance: %w", err)
		}
	}

	_, clubBalanceAfter, err := changeClubBalance(ctx, qtx, params.ClubID, newClubDelta-oldClubDelta, now)
	if err != nil {
		return nil, err
	}
	clubBalanceBefore := clubBalanceAfter - newClubDelta

	txDate := old.TransactionDate
	if !params.TransactionDate.IsZero() {
		txDate = params.TransactionDate.UTC().Truncate(24 * time.Hour).Add(12 * time.Hour)
	}

	if _, err := qtx.UpdateTransaction(ctx, db.UpdateTransactionParams{
		ID:                  id,
		PlayerID:            params.PlayerID,
		TransactionType:     string(params.TransactionType),
		Amount:              int32(params.Amount),
		Description:         sql.NullString{String: params.Description, Valid: params.Description != ""},
		PlayerBalanceBefore: toNullInt32(playerBalanceBefore),
		PlayerBalanceAfter:  toNullInt32(playerBalanceAfter),
		ClubBalanceBefore:   int32(clubBalanceBefore),
		ClubBalanceAfter:    int32(clubBalanceAfter),
		TransactionDate:     txDate,
		UpdatedAt:           now,
	}); err != nil {
		return nil, fmt.Errorf("failed to update transaction: %w", err)
	}

	if err := tx.Commit(); err != nil {
		return nil, fmt.Errorf("failed to commit transaction: %w", err)
	}
	// Reload with the joined player name for the response.
	return r.GetByID(ctx, id)
}
